{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "Direct human data for ranolazine, the query molecule, report oral bioavailability of 35–50% from slow-release tablets, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Lidocaine, which shares the 2,6-dimethylanilide acetamide and a basic amine, has human oral F values around 35–42%, supporting F ≥ 20% for this amide/amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Recainam, a 2,6-dimethylphenyl amide/urea antiarrhythmic with a basic side chain, shows absolute F of 73–84% in healthy men, supporting high oral bioavailability for the xylidine amide class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tocainide, another 2,6-dimethylanilide, is essentially completely bioavailable (81–100%) after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Propranolol, an aryloxypropanolamine, has a human absolute F of about 19% in one study, indicating first-pass liability; this is only partially transferable because the query's piperazine-acetanilide structure and direct ranolazine data differ.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct ranolazine evidence (35–50% F) and multiple close analogues sharing the 2,6-dimethylanilide amide (lidocaine, recainam, tocainide) support oral bioavailability above 20%; the only sub-20 analogue, propranolol, is less transferable due to different amine/amide architecture and is outweighed by direct data.",
  "evidence_gaps": [
    "The direct ranolazine record is from slow-release tablets and does not explicitly state comparison to IV, but the reported 35–50% range is still threshold-relevant.",
    "First-pass metabolism and transporter effects for the piperazine-acetanilide combination are not directly quantified in the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

